def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n >= 99:
        return 'D'

    opp_def = 0
    my_def = 0
    for m, o in history:
        if o == 'D':
            opp_def += 1
        if m == 'D':
            my_def += 1

    if opp_def == 0:
        if my_def == 0:
            if n >= 5:
                return 'D'
            return 'C'
        elif my_def == 1:
            if history[-1][0] == 'D':
                return 'C'
            else:
                return 'D'
        else:
            return 'D'

    last_me, last_opp = history[-1]

    recent_exploit = 0
    start = max(1, n - 6)
    for i in range(start, n):
        if history[i - 1][0] == 'C' and history[i][1] == 'D':
            recent_exploit += 1

    recent_opp_def = 0
    start5 = max(0, n - 5)
    for i in range(start5, n):
        if history[i][1] == 'D':
            recent_opp_def += 1

    if recent_exploit >= 2:
        return 'D'

    if n >= 10:
        opp_rate = opp_def / float(n)
        if opp_rate > 0.6:
            if rng.random() < 0.95:
                return 'D'
            return 'C'

    if last_opp == 'D':
        if last_me == 'D':
            if recent_exploit == 0 and rng.random() < 0.1:
                return 'C'
            return 'D'
        if recent_exploit >= 1:
            return 'D'
        if rng.random() < 0.8:
            return 'C'
        return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            return 'C'
        if recent_opp_def >= 3:
            if rng.random() < 0.3:
                return 'D'
            return 'C'
        return 'C'

    return 'C'
